public class Thermostat {
    private int temperature;
    private boolean ecoMode;

    public Thermostat(int temperature, boolean ecoMode) {
        this.temperature = temperature;
        this.ecoMode = ecoMode;
    }

    public String getStatus() {
        int heatBelow = ecoMode ? 65 : 68;
        int coolAbove = ecoMode ? 78 : 75;

        if (temperature < heatBelow) {
            return "Heating";
        } else if (temperature > coolAbove) {
            return "Cooling";
        } else {
            return "Idle";
        }
    }

    public String printStatusToDisplay() {
        return "Thermostat status: " + getStatus();
    }
}
